  'receita.k-saldo': { mede: 'Saldo vencido de empresas na data escolhida.', calcula: 'Soma das anuidades vencidas e não pagas na data escolhida; variação contra o saldo no mesmo ponto um ano antes.', fontes: INTERNO, regra: V1, limites: 'Parcelamentos em dia não contam.', acao: 'Cobrar primeiro os maiores saldos e os mais recentes; conferir se o CNPJ segue ativo.' },
  'receita.k-adimplencia': { mede: 'Empresas cobradas sem saldo vencido.', calcula: 'Cobradas sem saldo vencido na data escolhida dividido por cobradas; contra a meta do painel.', fontes: INTERNO, regra: V1, limites: 'Cobrada = com anuidade lançada no período.' },
  'receita.k-recuperacao': { mede: 'Quanto do saldo que já estava vencido no início do período foi recebido até a data escolhida.', calcula: 'Valor recebido dessas dívidas, dividido pelo saldo vencido no início do período.', fontes: INTERNO, regra: V1, limites: 'Só entram as dívidas que já existiam no início; pagamentos de dívidas novas ficam de fora.' },
  'receita.k-execucao': { mede: 'Execução orçamentária dos programas no período.', calcula: 'Executado dividido por planejado nos programas do modelo institucional.', fontes: 'Orçamento dos programas (modelo institucional demonstrativo).', regra: V1, limites: DEMO },
  'receita.k-potencial': { mede: 'Quanto o Conselho arrecadaria por ano se os estabelecimentos sem registro se registrassem.', calcula: 'Número de estabelecimentos com atividade da lista sem registro, multiplicado pela anuidade típica (mediana) das empresas registradas.', fontes: `${RECEITA} ${INTERNO}`, regra: V1, limites: 'É um teto teórico, porque parte desses estabelecimentos não é obrigada a se registrar.' },
  'receita.yoy': { mede: 'Arrecadação de empresas mês a mês contra o mesmo mês do ano anterior.', calcula: 'Anuidades e multas pela data do pagamento; linha = total do mesmo mês um ano antes.', fontes: INTERNO, regra: V1, limites: 'Vencimentos concentrados distorcem a comparação mensal.' },
  'receita.rg': { mede: 'Quanto do saldo vencido foi recuperado e há quanto tempo o saldo atual está vencido.', calcula: 'O medidor mostra a parte recuperada do saldo que estava vencido no início do período. As barras mostram o saldo vencido por faixa de atraso na data escolhida.', fontes: INTERNO, regra: V1, limites: 'A dívida antiga costuma ser recuperada pela dívida ativa, que fica fora desta leitura.' },
  'receita.tr': { mede: 'Onde está o saldo vencido: decomposição por regional, porte, atraso, atividade e RT.', calcula: 'Árvore de decomposição do saldo vencido na data escolhida, uma dimensão por coluna.', fontes: INTERNO, regra: V1, limites: 'Cada ramo soma ao total; a ordem das dimensões muda a leitura.' },
  'receita.or': { mede: 'Orçamento dos programas: planejado contra executado no período.', calcula: 'Soma do planejado e do executado por programa nos meses do período.', fontes: 'Orçamento dos programas (modelo institucional demonstrativo).', regra: V1, limites: DEMO },

