  'entidades.k-cadeiras': { mede: 'Cadeiras no plenário ocupadas por indicação de entidades e IES.', calcula: 'Soma dos conselheiros indicados por organização, por natureza.', fontes: ENTIDADES, regra: V2, limites: 'Composição demonstrativa fixa; em produção, a composição vigente do plenário por mandato.' },
  'entidades.k-repasses': { mede: 'Repasses pagos nos últimos 12 meses a entidades e IES.', calcula: 'Pagamentos de convênios, contratos e patrocínios pela data do pagamento; variação contra os 12 meses anteriores.', fontes: ENTIDADES, regra: V2, limites: 'Fluxo financeiro; não avalia mérito ou resultado.' },
