  'entidades.ec': { mede: 'Cadeiras no plenário por natureza da organização.', calcula: 'Cadeiras somadas por grupo: entidade de classe, IES pública, IES privada; com o número de organizações de cada grupo.', fontes: ENTIDADES, regra: V2, limites: 'Leitura descritiva da composição; sem juízo sobre representatividade.' },
  'entidades.er': { mede: 'Repasses por ano, natureza da organização e canal.', calcula: 'Pagamentos por ano do pagamento, grupo da organização e canal (convênio, contrato, patrocínio).', fontes: ENTIDADES, regra: V2, limites: 'Ano corrente parcial até a data escolhida.' },
  'entidades.ee': { mede: 'IES por natureza: parte EaD dos concluintes e cadeiras.', calcula: 'Para cada IES: % EaD (Censo), cadeiras e repasses; agrupadas por natureza.', fontes: `${ENTIDADES} ${INEP}`, regra: V2, limites: '% EaD pela oferta de concluintes, não por matrícula.' },
  'entidades.et': { mede: 'Tabela por organização: natureza, % EaD, cadeiras, convênios, contratos, patrocínios e repasses.', calcula: 'Uma linha por organização registrada até a data escolhida, com os instrumentos e pagamentos até a data escolhida.', fontes: `${ENTIDADES} ${INEP}`, regra: V2, limites: 'Leitura neutra: a tabela mostra os fatos lado a lado e não calcula relação entre cadeiras e repasses.' },

