  'controle.k-fim': { mede: 'Parte da despesa em atividades-fim.', calcula: 'Funções fiscalização, atendimento e institucional dividido por total.', fontes: CONSELHO, regra: V2, limites: 'Classificação administrativa; medida descritiva.' },
  'controle.k-execucao': { mede: 'Execução orçamentária do ano corrente até a data escolhida.', calcula: 'Realizado dividido por orçado nos meses do ano até a data escolhida.', fontes: CONSELHO, regra: V2, limites: 'Orçado mensalizado por duodécimos no cenário.' },
  'controle.k-diarias': { mede: 'Diárias e passagens nos últimos 12 meses.', calcula: 'Soma do valor das diárias pela competência, todas as categorias; variação contra os 12 meses anteriores.', fontes: CONSELHO, regra: V2, limites: 'Inclui deslocamentos de fiscalização, que são atividade-fim.' },
  'controle.k-concentracao': { mede: 'Concentração dos empenhos nos cinco maiores fornecedores.', calcula: 'Empenhado nos 5 maiores dividido por empenhado total nos últimos 12 meses; HHI como complemento.', fontes: CONSELHO, regra: V2, limites: 'Concentração alta pode refletir contratos grandes e legítimos (por exemplo, TI ou locação).' },
