  'controle.cf': { mede: 'Despesa em atividades-fim e atividades-meio por ano.', calcula: 'Realizado por ano, dividido entre funções-fim e funções-meio; ano corrente até a data escolhida.', fontes: CONSELHO, regra: V2, limites: 'Medida descritiva, sem nível “certo”.' },
  'controle.cn': { mede: 'Despesa por natureza: orçado contra realizado, últimos 12 meses.', calcula: 'Soma por natureza de despesa (pessoal, diárias, terceiros, material, investimentos, transferências, outras).', fontes: CONSELHO, regra: V2, limites: 'Naturezas seguem a classificação orçamentária do Conselho.' },
  'controle.cd': { mede: 'Diárias por categoria de beneficiário e por mês.', calcula: 'Quantidade, valor e quilometragem por categoria nos últimos 12 meses; série mensal de 24 meses.', fontes: CONSELHO, regra: V2, limites: 'Mostra onde o deslocamento acontece; não avalia a necessidade de cada viagem.' },
  'controle.cs': { mede: 'Despesa da sede contra o território e custo por ação fiscal por regional.', calcula: 'Realizado com centro de custo na sede dividido por nas regionais; custo por ação = despesa de fiscalização da regional dividido por ações fiscais da regional em 12 meses.', fontes: `${CONSELHO} ${FISCAL}`, regra: V2, limites: 'Custo por ação varia com a distância e o tipo de ação; comparar regionais com cautela.' },
  'controle.cr': { mede: 'Composição da receita por fonte e ano.', calcula: 'Receita realizada por fonte (anuidades PF, anuidades PJ, taxas de ART, multas, outras) por ano; ano corrente até a data escolhida.', fontes: CONSELHO, regra: V2, limites: 'Receita realizada, não prevista.' },
  'controle.cc': { mede: 'Fornecedores, empenhos, contratos e concentração.', calcula: 'Empenhado e pago por fornecedor nos últimos 12 meses; contratos vigentes por modalidade, com aditivo e vencendo em 90 dias.', fontes: CONSELHO, regra: V2, limites: 'Concentração alta não é irregularidade.' },
  'controle.cp': { mede: 'Pessoal por função: efetivos, comissionados e custo mensal.', calcula: 'Quadro na data escolhida por função; custo = folha mensal com encargos.', fontes: CONSELHO, regra: V2, limites: 'Quadro demonstrativo; em produção, a folha por lotação.' },
  'controle.ck': { mede: 'Capacitação: quantas atividades houve, quantas pessoas participaram e quanto custou cada participante.', calcula: 'Cursos e ações de orientação no período, participantes identificados e o custo executado dividido pelo número de participantes.', fontes: 'Programas institucionais e orçamento (modelo demonstrativo).', regra: V2, limites: 'O bloco mostra só custo e alcance. Medir o efeito da capacitação exigiria um estudo próprio.' },
  'controle.dp': { mede: 'Despesa publicada do Crea-SP: por exercício e composição por subgrupo.', calcula: 'Valores lidos do Portal da Transparência, versionados no repositório com a data de captura.', fontes: 'Portal da Transparência do Crea-SP (dado real).', regra: V1, limites: 'Retrato na data de captura; não responde aos filtros nem à data de referência.' },

