  'atendimento.k-solicitacoes': { mede: 'Solicitações abertas no período e a parte vinda de empresas.', calcula: 'Contagem pela data de abertura; variação contra o mesmo período do ano anterior.', fontes: 'Sistema de atendimento do Crea-SP.', regra: V1, limites: 'Território = local do atendimento; câmara não se aplica.' },
  'atendimento.k-tempo': { mede: 'Tempo mediano de resolução e abertas com prazo vencido.', calcula: 'Mediana dos dias entre abertura e resolução das resolvidas até a data escolhida.', fontes: 'Sistema de atendimento do Crea-SP.', regra: V1, limites: 'Abertas não entram na mediana.' },
