  'atendimento.k-pendencias': { mede: 'Pendências de qualidade cadastral abertas.', calcula: 'Eventos de qualidade não resolvidos na data escolhida, por tipo.', fontes: INTERNO, regra: V1, limites: 'Pendência afeta cobrança, fiscalização e indicadores.', acao: 'Corrigir na origem, começando pelo tipo mais frequente.' },
